#include <cstdio>
#include <algorithm>
#include <vector>

using namespace std;

const int N = 2005;

int n, m;
vector<int> e[N];
int d[N], mx[N], q[N];

void bfs(int u) {
    for (int i = 1; i <= n; i++)
        d[i] = n + 1;
    d[u] = 0;
    q[1] = u;
    int ql = 1, qr = 1;
    while (ql <= qr) {
        int x = q[ql++];
        for (auto y : e[x])
            if (d[x] + 1 < d[y]) {
                d[y] = d[x] + 1;
                q[++qr] = y;
            }
    }
    mx[u] = d[q[qr]];
}

int main() {
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= m; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        e[u].emplace_back(v);
        e[v].emplace_back(u);
    }
    int ans = 1;
    for (int i = 1; i <= n; i++) {
        bfs(i);
        if (mx[i] < mx[ans])
            ans = i;
    }
    printf("%d\n", ans);
    return 0;
}

#include <cstdio>
#include <algorithm>

using namespace std;

const int N = 305;

int n;
int c[N], a[N];
int f[N][N];
int ans;

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++)
        scanf("%d", &c[i]);
    for (int i = 1; i <= n; i++)
        scanf("%d", &a[i]);
    sort(c + 1, c + n + 1);
    for (int i = n; i >= 1; i--)
        for (int j = 1; j <= n; j++)
            for (int k = i; k <= n; k++) {
                int diff = 0;
                if (i > 1)
                    diff = c[n - j + 1] - c[j];
                f[j][k] = max(f[j][k], f[j - 1][k - i] + a[i] + diff);
                if (k == n)
                    ans = max(ans, f[j][k]);
            }
    printf("%d\n", ans);
    return 0;
}
